# Builds DCScaffold-Setup.exe (repository root) on Windows: Go (https://go.dev/dl/) and NSIS 3 (https://nsis.sourceforge.io).
#   .\installer\build.ps1 -UpdateRepo owner/repo    GitHub repository checked for updates (default Djason16/dc-scaffold, '' = no update check)
# The icon and version information of DCScaffold.exe come from launcher\rsrc_windows_amd64.syso (regenerated by build.sh).
param([string]$UpdateRepo = 'Djason16/dc-scaffold')
$ErrorActionPreference = 'Stop'
Set-Location $PSScriptRoot
$version = (Get-Content ..\VERSION -First 1).Trim()
New-Item -ItemType Directory -Path build -Force | Out-Null

# 1. Go launcher
Push-Location ..\launcher
$env:GOOS = 'windows'; $env:GOARCH = 'amd64'
go build -trimpath -ldflags="-s -w -H windowsgui -X main.version=$version -X main.updateRepo=$UpdateRepo" -o ..\installer\build\DCScaffold.exe .
Pop-Location

# 2. License for the license page
Copy-Item ..\LICENSE build\LICENSE.txt

# 3. Installer
$makensis = @((Get-Command makensis -ErrorAction SilentlyContinue).Source, "${env:ProgramFiles(x86)}\NSIS\makensis.exe") | Where-Object { $_ -and (Test-Path $_) } | Select-Object -First 1
if (-not $makensis) { throw 'NSIS not found: install it from https://nsis.sourceforge.io' }
& $makensis -V2 "-DVERSION=$version" dc-scaffold.nsi
Write-Host "DCScaffold-Setup.exe $version"
